package io.github.diodeme.ji.telemetry;

import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

/** Allow-list policy that excludes prompts, content, raw tool/file output, headers, and secrets. */
public final class TelemetryPolicy {
    private static final Set<String> SAFE_EXACT = Set.of(
            "ji.host.id", "ji.workspace.id", "ji.session.id", "ji.operation.id", "ji.operation.kind",
            "ji.operation.recovery", "ji.operation.outcome", "ji.branch.id", "ji.turn.id", "ji.attempt.number",
            "ji.provider.family", "ji.provider.model", "ji.provider.streaming", "ji.http.status_code",
            "ji.usage.input_tokens", "ji.usage.output_tokens", "ji.usage.cache_read_tokens",
            "ji.usage.cache_write_tokens", "ji.usage.reasoning_tokens", "ji.usage.total_tokens",
            "ji.tool.name", "ji.tool.is_error", "ji.error.code", "ji.error.type", "ji.retry.attempt",
            "ji.chunk.count", "ji.duration.ms", "ji.item.count", "ji.bytes", "ji.status", "unit");

    public static TelemetryPolicy safeDefaults() {
        return new TelemetryPolicy();
    }

    public Map<String, TelemetryValue> sanitize(Map<String, TelemetryValue> attributes) {
        var safe = new TreeMap<String, TelemetryValue>();
        if (attributes == null) return Map.of();
        for (var entry : attributes.entrySet()) {
            String name = entry.getKey();
            TelemetryValue value = entry.getValue();
            if (name != null && value != null && SAFE_EXACT.contains(name)) safe.put(name, copy(value));
        }
        return Map.copyOf(safe);
    }

    private static TelemetryValue copy(TelemetryValue value) {
        return switch (value) {
            case TelemetryValue.Text item -> new TelemetryValue.Text(item.value());
            case TelemetryValue.Number item -> new TelemetryValue.Number(item.value());
            case TelemetryValue.Flag item -> new TelemetryValue.Flag(item.value());
            case TelemetryValue.Texts item -> new TelemetryValue.Texts(item.value());
            case TelemetryValue.Numbers item -> new TelemetryValue.Numbers(item.value());
            case TelemetryValue.Flags item -> new TelemetryValue.Flags(item.value());
        };
    }
}
